/** CLI-owned; regenerated by setu generate module or setu generate … --module <name>. */
import type { IRouterApi, IServiceRegistry } from '@setu-ts/common';
import { registerEventsRoutes } from './events.controller.ts';

/** Registers the feature routes. */
export function registerEventsModule(router: IRouterApi, services?: IServiceRegistry): void {
  registerEventsRoutes(router, services);
}
